44	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
45	    @PostMapping("/seed")
46	    @SuppressWarnings("unchecked")
47	    public void seed(@RequestBody Map<String, Object> fixture) {
48	        List<Map<String, Object>> clients =
49	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
50	        for (Map<String, Object> c : clients) {
51	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
52	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
